    let selectedIds = new Set();
    let currentFilter = 'all';
    let showSelectedOnlyMode = false;

    function init() {
      renderCandidates();
      renderDistricts();
      renderReserved();
      renderSecured();
      updateTracker();
    }

    function renderCandidates() {
      const grid = document.getElementById('candidatesGrid');
      grid.innerHTML = '';

      const query = document.getElementById('searchInput').value.trim().toLowerCase();

      let filtered = candidates.filter(c => {
        const matchesQuery = !query || 
          c.name.toLowerCase().includes(query) || 
          c.role.toLowerCase().includes(query) || 
          c.desc.toLowerCase().includes(query);

        let matchesFilter = true;
        if (currentFilter !== 'all') {
          matchesFilter = c.tags.includes(currentFilter);
        }

        let matchesSelected = true;
        if (showSelectedOnlyMode) {
          matchesSelected = selectedIds.has(c.id);
        }

        return matchesQuery && matchesFilter && matchesSelected;
      });

      if (filtered.length === 0) {
        grid.innerHTML = `




לא נמצאו מועמדים התואמים את החיפוש או הסינון

נסה לשנות את מילות החיפוש או לבטל את הסינון

        `;
        return;
      }

      filtered.forEach(c => {
        const isSelected = selectedIds.has(c.id);
        const card = document.createElement('div');
        card.className = `candidate-card ${isSelected ? 'selected' : ''}`;
        card.onclick = () => toggleCandidate(c.id);

        const imageHtml = c.img ? `


${c.initials}
        ` : `

${c.initials}
        `;

        card.innerHTML = `


            #${c.id}




            ${imageHtml}




${c.name}

${c.role}

${c.desc}




              ${isSelected ? `

                נבחר (לחץ להסרה)
              ` : `

                הוסף לבחירה
              `}


        `;

        grid.appendChild(card);
      });
    }

    function toggleCandidate(id) {
      if (selectedIds.has(id)) {
        selectedIds.delete(id);
      } else {
        if (selectedIds.size >= 12) {
          showToast("⚠️ ניתן לבחור עד 12 מועמדים ברשימה הארצית בלבד! הסר מועמד כדי לבחור אחר.");
          return;
        }
        selectedIds.add(id);
      }
      updateTracker();
      renderCandidates();
    }

    function updateTracker() {
      const count = selectedIds.size;
      const countDisplay = document.getElementById('selectedCountDisplay');
      countDisplay.textContent = `${count} / 12`;
      if (count === 12) {
        countDisplay.classList.add('full');
      } else {
        countDisplay.classList.remove('full');
      }

      const pct = (count / 12) * 100;
      document.getElementById('progressBar').style.width = `${pct}%`;

      const viewBtn = document.getElementById('viewSelectedBtn');
      viewBtn.textContent = showSelectedOnlyMode ? `הצג את כל המועמדים (${candidates.length})` : `הצג נבחרים בלבד (${count})`;
    }

    function setFilter(tag, el) {
      document.querySelectorAll('.filter-tag').forEach(b => b.classList.remove('active'));
      el.classList.add('active');
      currentFilter = tag;
      renderCandidates();
    }

    function applyFilters() {
      renderCandidates();
    }

    function filterSelectedOnly() {
      showSelectedOnlyMode = !showSelectedOnlyMode;
      updateTracker();
      renderCandidates();
    }

    function resetSelections() {
      if (selectedIds.size === 0) return;
      if (confirm('האם לאפס את כל המועמדים שבחרת?')) {
        selectedIds.clear();
        showSelectedOnlyMode = false;
        updateTracker();
        renderCandidates();
        showToast('הבחירות אופסו בהצלחה');
      }
    }

    function switchTab(tabId, el) {
      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      if (el) el.classList.add('active');

      document.getElementById('tab-national').style.display = tabId === 'national' ? 'block' : 'none';
      document.getElementById('tab-districts').style.display = tabId === 'districts' ? 'block' : 'none';
      document.getElementById('tab-reserved').style.display = tabId === 'reserved' ? 'block' : 'none';
      document.getElementById('tab-secured').style.display = tabId === 'secured' ? 'block' : 'none';
    }

    function renderDistricts() {
      const c = document.getElementById('districtsContainer');
      c.innerHTML = extraData.districts.map(d => `




            📍 ${d.name}
            ${d.candidates.length} מתמודדים



            ${d.candidates.map(name => `${name}`).join('')}


      `).join('');
    }

    function renderReserved() {
      const c = document.getElementById('reservedContainer');
      c.innerHTML = extraData.reserved.map(r => `




            ⭐ ${r.category}
            ${r.quota} (${r.candidates.length} מתמודדים)



            ${r.candidates.map(name => `${name}`).join('')}


      `).join('');
    }

    function renderSecured() {
      const c = document.getElementById('securedContainer');
      c.innerHTML = extraData.secured.map(s => `



${s.name}

${s.role}

      `).join('');
    }

    function openBallotModal() {
      const modal = document.getElementById('ballotModal');
      const listContainer = document.getElementById('ballotListContainer');
      document.getElementById('modalSelectedCount').textContent = selectedIds.size;

      if (selectedIds.size === 0) {
        listContainer.innerHTML = `



טרם בחרת מועמדים לרשימה הארצית

לחץ על כרטיס מועמד כדי להוסיפו לפתק הבחירה שלך (עד 12 מועמדים)

        `;
      } else {
        const selectedList = candidates.filter(c => selectedIds.has(c.id));
        listContainer.innerHTML = selectedList.map((c, idx) => `



${idx + 1}



${c.name}

${c.role}


        `).join('');
      }

      modal.classList.add('active');
    }

    function closeBallotModal() {
      document.getElementById('ballotModal').classList.remove('active');
    }

    function copyBallotToClipboard() {
      if (selectedIds.size === 0) {
        showToast('אין מועמדים להעתקה');
        return;
      }
      const selectedList = candidates.filter(c => selectedIds.has(c.id));
      const text = "רשימת 12 המועמדים שלי בפריימריז הליכוד 2026:
" + 
        selectedList.map((c, i) => `${i+1}. ${c.name} (${c.role})`).join('
');

      navigator.clipboard.writeText(text).then(() => {
        showToast('הרשימה הועתקה ללוח בהצלחה!');
      }).catch(() => {
        showToast('שגיאה בהעתקה ללוח');
      });
    }

    function showToast(msg) {
      const toast = document.getElementById('toast');
      document.getElementById('toastMsg').textContent = msg;
      toast.classList.add('show');
      setTimeout(() => {
        toast.classList.remove('show');
      }, 3000);
    }

    window.onclick = function(event) {
      const modal = document.getElementById('ballotModal');
      if (event.target === modal) {
        closeBallotModal();
      }
    };

    document.addEventListener('DOMContentLoaded', init);
